# Collect names from staging outputs
# Always read names from an un-linked copy of the transform output, so this notebook can be rerun freely
LATEST_DIR    = f"{ROOT}/{STAGING_DIR}"                        # OUTPUT/TRANSFORM/latest
PRE_USERS_DIR = f"{ROOT}/OUTPUT/TRANSFORM/latest_pre_users"    # untouched copy of the transform output
MARKER        = "_users_linked.json"

def exists(path):
    try:
        mssparkutils.fs.ls(path)
        return True
    except Exception:
        return False

if any(f.name == MARKER for f in mssparkutils.fs.ls(LATEST_DIR)):
    if not exists(PRE_USERS_DIR):
        raise RuntimeError("latest is already user-linked and there's no pre-users copy. Rerun the transform notebook once.")
    SOURCE_DIR, FRESH = PRE_USERS_DIR, False    # rerun: read the saved original
else:
    SOURCE_DIR, FRESH = LATEST_DIR, True        # new transform output
print(f"Reading names from: {SOURCE_DIR}")

SPLIT = r"\s*(?:/|,|&|\band\b|\||\n)\s*"
found   = {}   # name -> set of "file:column"
skipped = []

def readable_csvs(folder):
    """Data CSVs only: skips _metadata files, empty files and unreadable files."""
    for f in mssparkutils.fs.ls(folder):
        if not f.name.lower().endswith(".csv") or f.name.startswith("_"):
            continue
        if not f.isDir and f.size == 0:
            skipped.append((f.name, "empty file"))
            continue
        try:
            yield f, spark.read.option("header", True).option("multiLine", True).csv(f.path).toPandas()
        except Exception as e:
            skipped.append((f.name, type(e).__name__))

for f, df in readable_csvs(SOURCE_DIR):
    for col in [c for c in USER_COLUMNS if c in df.columns]:
        print(f"Scanning {f.name} -> {col}")
        for val in df[col].dropna():
            for name in re.split(SPLIT, str(val)):
                if name.strip():
                    found.setdefault(name.strip(), set()).add(f"{f.name}:{col}")

for name, why in skipped:
    print(f"Skipped {name}: {why}")
print(f"Distinct names found: {len(found)}")

# Match names to Entra
def pick(hits):
    """One hit -> it. Several (same person, two accounts) -> prefer active, then the one with a mailbox."""
    hits = list(dict.fromkeys(hits))
    if len(hits) <= 1:
        return hits[0] if hits else None
    rows = ENTRA_BY_ID.loc[hits]
    for mask in [~rows["deleted"], rows["mail"].notna()]:
        if mask.sum() == 1:
            return rows[mask].index[0]
        if mask.sum() > 1:
            rows = rows[mask]
    return None   # still ambiguous -> needs NAME_OVERRIDES

def match(name):
    if name in NAME_OVERRIDES and NAME_OVERRIDES[name] is None:
        return None, "ignored"
    if name not in NAME_OVERRIDES and len(name.split()) > MAX_NAME_WORDS:
        return None, "not a name"
    if name in NAME_OVERRIDES:
        key  = NAME_OVERRIDES[name].lower()
        uid  = pick(by_upn.get(key, []) or by_mail.get(key, []))
        return (uid, "override") if uid else (None, "override not found")
    k = clean_display(name)
    for method, idx in [("displayName", by_display), ("first+last", by_name)]:
        hits = idx.get(k, [])
        if hits:
            uid = pick(hits)
            return (uid, method) if uid else (None, f"ambiguous ({len(set(hits))} accounts)")
    return None, "unmatched"

rows = []
for name, where in sorted(found.items()):
    uid, method = match(name)
    rows.append({"name": name, "entraId": uid, "method": method, "foundIn": "; ".join(sorted(where))})
name_map = pd.DataFrame(rows)

matched   = name_map[name_map.entraId.notna()]
unmatched = name_map[name_map.entraId.isna()]
print(f"Matched: {len(matched)} | Unmatched/ambiguous: {len(unmatched)}")
display(unmatched) if len(unmatched) else print("All names matched")

# Apply user ids -> new version of latest (only when LINK_IDS_INTO_TRANSFORM = True)
if not LINK_IDS_INTO_TRANSFORM:
    print("Skipped: TRANSFORM/latest keeps names; nb_s62a_schema_align maps them to ids via REFERENCE/users.csv")
else:
    # Apply user ids -> new version of latest
    from datetime import datetime
    import json

    RUN_ID      = datetime.utcnow().strftime("%Y%m%d_%H%M%S") + "_users"
    VERSION_DIR = f"{ROOT}/OUTPUT/TRANSFORM/{RUN_ID}"

    # First run on a new transform output: save an untouched copy for future reruns
    if FRESH:
        if exists(PRE_USERS_DIR):
            mssparkutils.fs.rm(PRE_USERS_DIR, True)
        mssparkutils.fs.cp(LATEST_DIR, PRE_USERS_DIR, True)
        SOURCE_DIR = PRE_USERS_DIR
        print("Saved pre-users copy of the transform output")

    name_to_id = dict(zip(name_map["name"], name_map["id"]))
    issues = []

    def to_id(val, file, col):
        if pd.isna(val):
            return val
        names = [n.strip() for n in re.split(SPLIT, str(val)) if n.strip()]
        ids   = [name_to_id.get(n) for n in names]
        if len(names) > 1:
            issues.append((file, col, val, "multiple names, first one used"))
        if ids and ids[0] is None:
            issues.append((file, col, val, "no user id"))
        return ids[0] if ids else None

    # 1. Build the new version from the untouched copy
    linked, rewritten = [], {}
    for f, df in readable_csvs(SOURCE_DIR):
        cols = [c for c in USER_COLUMNS if c in df.columns]
        if cols:
            for col in cols:
                df[col] = df[col].map(lambda v, c=col, n=f.name: to_id(v, n, c))
            rewritten[f.name] = df
            linked.append({"file": f.name, "columns": cols})

    for f in mssparkutils.fs.ls(SOURCE_DIR):
        if f.name == MARKER:
            continue
        dest = f"{VERSION_DIR}/{f.name}"
        if f.name in rewritten:
            mssparkutils.fs.put(dest, rewritten[f.name].to_csv(index=False), True)
            print(f"Linked {f.name}: {[l['columns'] for l in linked if l['file'] == f.name][0]}")
        else:
            mssparkutils.fs.cp(f.path, dest, True)

    # 2. Marker
    marker = {"run_id": RUN_ID, "source": SOURCE_DIR, "linked": linked, "issues": len(issues),
              "created_utc": datetime.utcnow().isoformat()}
    mssparkutils.fs.put(f"{VERSION_DIR}/{MARKER}", json.dumps(marker, indent=1), True)

    # 3. Promote: replace latest with the new version
    mssparkutils.fs.rm(LATEST_DIR, True)
    mssparkutils.fs.cp(VERSION_DIR, LATEST_DIR, True)

    if issues:
        write_csv(pd.DataFrame(issues, columns=["file", "column", "value", "issue"]),
                  "OUTPUT/VALIDATION/USERS/linking_issues.csv")
    print(f"New version: OUTPUT/TRANSFORM/{RUN_ID} -> promoted to latest | linking issues: {len(issues)}")
